"""The Python view of the records: pydantic models and StrEnums for the SDK (agent/src/probe/generated)."""

from __future__ import annotations

import json
import textwrap
from enum import Enum

from pydantic import BaseModel

from ..probe_contracts import Contracts
from .field_types import FieldType, default_of, describe, doc_of

HEADER = (
    "# GENERATED by `python -m probe_contracts.codegen` from contracts/probe_contracts/records.\n"
    "# Do not edit: change the record there and rerun.\n"
)

#: Where the SDK keeps 3.11's StrEnum for 3.10 (agent/tests/test_py310_compat.py), as
#: agent/tools/codegen/gen_models.py writes it for the other generated models.
STR_ENUM_MODULE = "probe.foundation.compat.compat"

PRELUDE = '''"""The shared domain records (probe-contracts), as the SDK reads them."""

from __future__ import annotations

from datetime import datetime
from typing import Literal
from uuid import UUID

from pydantic import BaseModel, ConfigDict, Field

from {str_enum_module} import StrEnum

__all__ = [
{names}]
'''


def render_type(field_type: FieldType) -> str:
    if field_type.kind == "scalar":
        return {"uuid": "UUID"}.get(field_type.name, field_type.name)
    if field_type.kind == "optional":
        return f"{render_type(field_type.inner)} | None"
    if field_type.kind == "list":
        return f"list[{render_type(field_type.inner)}]"
    if field_type.kind == "literal":
        return f"Literal[{', '.join(json.dumps(v) for v in field_type.values)}]"
    return field_type.name


def _docstring(cls: type, indent: str) -> str:
    text = doc_of(cls)
    if not text:
        return ""
    if "\n" not in text:
        return f'{indent}"""{text}"""\n\n'
    return f'{indent}"""{textwrap.indent(text, indent).lstrip()}\n{indent}"""\n\n'


def _enum(cls: type[Enum]) -> str:
    lines = [f"class {cls.__name__}(StrEnum):\n", _docstring(cls, "    ")]
    lines += [f"    {member.name} = {json.dumps(member.value)}\n" for member in cls]
    return "".join(lines)


def _default(info, field_type: FieldType) -> str:
    default = default_of(info)
    if default.required:
        return ""
    if default.factory:
        return f" = Field(default_factory={default.factory})"
    value = default.value
    if isinstance(value, Enum):
        return f" = {type(value).__name__}.{value.name}" if field_type.kind == "enum" else f" = {json.dumps(value.value)}"
    return f" = {json.dumps(value)}" if isinstance(value, str) else f" = {value!r}"


def _model(cls: type[BaseModel], frozen: bool) -> str:
    lines = [f"class {cls.__name__}(BaseModel):\n", _docstring(cls, "    ")]
    if frozen:
        lines.append("    model_config = ConfigDict(frozen=True)\n\n")
    for name, info in cls.model_fields.items():
        field_type = describe(info.annotation)
        lines.append(f"    {name}: {render_type(field_type)}{_default(info, field_type)}\n")
    return "".join(lines)


def render_python(contracts: Contracts) -> str:
    names = [c.__name__ for c in (*contracts.enums, *contracts.nested, *contracts.records)]
    blocks = [_enum(e) for e in contracts.enums]
    blocks += [_model(m, frozen=False) for m in contracts.nested]
    blocks += [_model(r, frozen=True) for r in contracts.records]
    prelude = PRELUDE.format(str_enum_module=STR_ENUM_MODULE,
                             names="".join(f'    "{n}",\n' for n in sorted(names)))
    return HEADER + prelude + "".join(f"\n\n{block}" for block in blocks)
